// Visit every distinct baseline eight-clique, or stop after every pair of demands is witnessed. For a pair to obstruct, each singleton demand must pass separately.
use std::io::{self,Read};struct Q{rows:Vec<u32>,qs:Vec<u32>,adj:Vec<Vec<usize>>,co:Vec<Vec<u64>>,w:Vec<Vec<usize>>,n:u64,full:bool}
impl Q{fn visit(&mut self,opts:&[usize],p:&mut Vec<usize>){if self.full{return}if p.len()==8{self.n+=1;let ids:Vec<_>=(0..self.qs.len()).filter(|&i|p.iter().filter(|&&j|self.rows[j]&self.qs[i]==0).count()<=2).collect();let mut m=vec![0;(self.qs.len()+63)/64];for &i in &ids{m[i/64]|=1u64<<(i%64)}for i in ids{if self.w[i].is_empty(){self.w[i]=p.clone()}for k in 0..m.len(){self.co[i][k]|=m[k]}}self.full=self.co.iter().all(|r|r.iter().map(|x|x.count_ones()as usize).sum::<usize>()==self.qs.len());return}for(k,&i)in opts.iter().enumerate(){if opts.len()-k<8-p.len()||self.full{break}let a:Vec<_>=opts[k+1..].iter().copied().filter(|j|self.adj[i].binary_search(j).is_ok()).collect();p.push(i);self.visit(&a,p);p.pop();}}}
fn main(){let mut s=String::new();io::stdin().read_to_string(&mut s).unwrap();let mut it=s.lines().map(|l|l.split_whitespace().map(|x|x.parse::<u32>().unwrap()).collect::<Vec<_>>());let rows=it.next().unwrap();let seven=it.next().unwrap();let qs=it.next().unwrap();let n=rows.len();let d=qs.len();let miss:Vec<Vec<u64>>=rows.iter().map(|s|{let mut m=vec![0;(seven.len()+63)/64];for(i,q)in seven.iter().enumerate(){if s&q==0{m[i/64]|=1u64<<(i%64)}}m}).collect();let adj=(0..n).map(|i|(i+1..n).filter(|&j|miss[i].iter().zip(&miss[j]).all(|(x,y)|x&y==0)).collect()).collect();let mut a=Q{rows,qs,adj,co:vec![vec![0;(d+63)/64];d],w:vec![vec![];d],n:0,full:false};a.visit(&(0..n).collect::<Vec<_>>(),&mut vec![]);let good:Vec<_>=(0..d).filter(|&i|!a.w[i].is_empty()).collect();let mut ct=0;for(i,&x)in good.iter().enumerate(){for &y in &good[i+1..]{if a.co[x][y/64]>>(y%64)&1==0{if ct==0{println!("{} {}\n{:?}\n{:?}",a.qs[x],a.qs[y],a.w[x],a.w[y])}ct+=1}}}println!("{} {} {} {} {}",a.n,a.full as u8,d,good.len(),ct)}
